SAMPLE_POLICY = dict(user_toks=999999, asst_toks=999999, call_toks=999999, result_toks=999999)
_SAMPLE_SKIP = ('dojo_start()', 'dojo_score(', '# kata', '%cd ')

def dojo_sample(src):
    "The completed dojo's substantive calls rendered as a compact sample session"
    pairs,out = dojo_round(src),[]
    for call,result in zip(pairs[::2],pairs[1::2]):
        if not _cell(call).lstrip().startswith(_SAMPLE_SKIP): out += [call,result]
    return compact_chat(items2chat(out), **SAMPLE_POLICY)

