# %% ../nbs/01_codexdojo.ipynb #f1c3a7b5
async def prep_dojo(
    cwd=None, # Project to start in; current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
    codex_home=None, # Alternate Codex home, primarily for tests
):
    "Create a thread containing the template and return its id"
    items,meta = _load_reg(d)
    async with codex_client(codex_home) as codex: thread = await codex.create_thread(reid_items(items,'launch:'+uuid.uuid4().hex),cwd=cwd)
    if ds:=meta.get('doced'): _seed_doced(thread.id,ds)
    return thread.id

# %% ../nbs/01_codexdojo.ipynb #6bdbb30e
def _prompt_text(item,text):
    item = obj2dict(item)
    item['content'] = [dict(type='input_text',text=text)]
    return item

async def append_dojo(
    sid=None, # Thread id to append to; newest thread for the project if None
    cwd=None, # Project directory; current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
    codex_home=None, # Alternate Codex home
):
    "Append the template to an existing thread and return its id"
    items,meta = _load_reg(d)
    sid,path = resolve_thread(sid,codex_home or CODEX_HOME) if sid else project_thread(cwd or '.',codex_home or CODEX_HOME)
    tail = load_recs(path)
    items = reid_items(items,f'append:{sid}:{len(tail)}')
    items[0] = _prompt_text(items[0],APPEND_PROMPT)
    async with codex_client(codex_home) as codex: await codex.append_thread(sid,items)
    _seed_doced(sid,meta.get('doced') or [],merge=True)
    return sid

# %% ../nbs/01_codexdojo.ipynb #c507e5da
def _is_prompt(x): return x.get('type')=='message' and x.get('role')=='user'

def _dealt(t): return any(re.match(_START_RE, _cell(x)) for x in t)

def strip_dojo(
    items, # Responses items in conversation order
):
    "Copy of `items` without the user turns that dealt a round (bare `dojo_start()`)"
    return _turns(items, _is_prompt).filter(_dealt, negate=True).concat()

def _strip(items):
    "`strip_dojo`, unless nothing else would remain to compact"
    s = strip_dojo(items)
    return s if items2chat(s) else items

# %% ../nbs/01_codexdojo.ipynb #3ca125e7
async def compact_dojo(
    sid=None, # Thread id to compact; newest thread for the project if None
    cwd=None, # Project directory; current directory if None
    d=None, # Template store dir; `TMPL_DIR` if None
    codex_home=None, # Alternate Codex home
):
    "Synthetically compact a thread with the compact DSL (previous dojo rounds removed first), then append the template round; returns its id"
    home = codex_home or CODEX_HOME
    sid,_ = resolve_thread(sid,home) if sid else project_thread(cwd or '.',home)
    compact_session(sid,home,strip=_strip)
    return await append_dojo(sid,cwd,d,codex_home)

# %% ../nbs/01_codexdojo.ipynb #7844e48b
@call_parse(nested=True, pos=['sess'])
def main(
    sess:str=None, # Thread id; the project's newest where omitted
    Resume:bool=False, # Append the round to an existing thread after compaction, then resume it
    Compact:bool=False, # Synthetically compact the thread with the compact DSL, then append the round and resume
    sid:bool=False, # Print the prepared thread id instead of launching codex
    capture:bool=False, # Run a clean round in a bare Codex child and store it
    current:bool=False, # Store the clean round an existing thread already played (`capture_current`)
):
    "Prepare a Codex thread opening with the worked round and launch `codex resume` on it; template maintenance is `dojobuild`"
    if capture: return capture_dojo()
    if current: return capture_current(sess)
    if Resume: s = asyncio.run(append_dojo(sess))
    elif Compact: s = asyncio.run(compact_dojo(sess))
    else:
        if sess: sys.exit(f"unexpected argument {sess!r}: a fresh launch takes no thread, and codex flag values need --flag=value form")
        s = asyncio.run(prep_dojo())
    if sid: return print(s)
    os.execvp('codex', ['codex', 'resume', s, *launch_config('codex'), *sys.argv[1:]])
